function ticketTurns(tickets, position) {
    const line = tickets.map((needed, who) => ({ who, needed }));
    let seconds = 0;
    while (line.length > 0) {
        const person = line.shift();
        seconds++;
        person.needed--;
        if (person.needed === 0) {
            if (person.who === position)
                return seconds;
        } else {
            line.push(person);
        }
    }
    return seconds;
}

function ticketTurns(tickets, position) {
    const needed = tickets[position];
    let seconds = 0;
    for (let i = 0; i < tickets.length; i++) {
        if (i <= position)
            seconds += Math.min(tickets[i], needed);
        else
            seconds += Math.min(tickets[i], needed - 1);
    }
    return seconds;
}
